SELECT id, customer_id, plan, start_date, end_date, monthly_fee, status, NTILE(10) OVER w_part AS monthly_fee_bucket, NTILE(5) OVER w_running AS monthly_fee_bucket_2, NTILE(4) OVER (ORDER BY monthly_fee, id) AS monthly_fee_bucket_3 FROM subscriptions WINDOW w_part AS (PARTITION BY customer_id ORDER BY monthly_fee DESC, id), w_running AS (PARTITION BY plan ORDER BY monthly_fee, id)
